// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
import { Star } from "@remotion/shapes";

const { fontFamily: interFamily } = loadInter();



export type SocialTestimonialProps = Record<string, any>;

const SocialTestimonial: React.FC<SocialTestimonialProps> = ({
  durationInSeconds = 5,
  testimonialText = '"I am just trying not to cry tears of joy everytime I use it"',
  starCount = 5,
  starColor = "#ffce3a",
  textColor = "#111111",
  bubbleColor = "#ffffff",
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const canvasScale = Math.min(width, height) / 1080;

  // Split text for word-by-word animation
  const words = testimonialText.split(" ");

  // --- Animations ---
  
  // Bubble Entrance
  const bubbleSpring = spring({ frame: frame - 15, fps, config: { damping: 12 } });
  const bubbleScale = interpolate(bubbleSpring, [0, 1], [0.8, 1]);
  const bubbleRotate = interpolate(bubbleSpring, [0, 1], [4, 0]);

  return (
    <AbsoluteFill style={{ 
      fontFamily: interFamily, 
      transition: "none",
      backgroundColor: transparentBackground ? "transparent" : backgroundColor
    }}>

      {/* Main Content Container */}
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        width: "100%",
        height: "100%",
        position: "absolute",
        zIndex: 10
      }}>
        
        {/* Animated Wrapper for Stars & Bubble */}
        <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${bubbleScale}) rotate(${bubbleRotate}deg)`,
          opacity: bubbleSpring
        }}>
          
          {/* Stars Array */}
          <div style={{
            position: "relative",
            zIndex: 10,
            display: "flex",
            gap: 12 * canvasScale,
            marginBottom: -35 * canvasScale // Pulls stars down to overlap bubble
          }}>
            {new Array(starCount).fill(0).map((_, i) => {
              const starScale = spring({ frame: frame - 25 - i * 3, fps, config: { damping: 10 } });
              return (
                <div key={i} style={{ 
                  transform: `scale(${starScale})`, 
                  filter: "drop-shadow(0 8px 12px rgba(0,0,0,0.25))" 
                }}>
                  <Star 
                    points={5} 
                    innerRadius={25 * canvasScale} 
                    outerRadius={50 * canvasScale} 
                    fill={starColor} 
                  />
                </div>
              );
            })}
          </div>

          {/* Chat Bubble Container (Drop shadow handles bubble + tail seamlessly) */}
          <div style={{
            filter: "drop-shadow(0 25px 45px rgba(0,0,0,0.18))",
            position: "relative",
            zIndex: 5
          }}>
            
            {/* Bubble Tail */}
            <div style={{
              position: "absolute",
              bottom: -16 * canvasScale,
              right: 120 * canvasScale,
              width: 60 * canvasScale,
              height: 60 * canvasScale,
              backgroundColor: bubbleColor,
              transform: "rotate(45deg)",
              borderRadius: 10 * canvasScale,
            }} />
            
            {/* Bubble Body */}
            <div style={{
              position: "relative",
              backgroundColor: bubbleColor,
              padding: `${60 * canvasScale}px ${90 * canvasScale}px`,
              borderRadius: 70 * canvasScale,
              maxWidth: width * 0.75,
              textAlign: "center"
            }}>
              
              {/* Testimonial Text */}
              <div style={{
                fontSize: 70 * canvasScale,
                fontStyle: "italic",
                fontWeight: 600,
                color: textColor,
                lineHeight: 1.15,
                letterSpacing: "-0.02em"
              }}>
                {words.map((word, i) => {
                  const wSpring = spring({ 
                    frame: frame - 40 - i * 2, 
                    fps, 
                    config: { damping: 14 } 
                  });
                  return (
                    <React.Fragment key={i}>
                      <span style={{
                        display: "inline-block",
                        opacity: wSpring,
                        transform: `translateY(${25 * (1 - wSpring)}px)`
                      }}>
                        {word}
                      </span>
                      {" "}
                    </React.Fragment>
                  );
                })}
              </div>
            </div>

          </div>
        </div>
      </div>
      
    </AbsoluteFill>
  );
};

export default SocialTestimonial;